class Solution { private lateinit var parent:IntArray;private fun find(value:Int):Int{if(parent[value]!=value)parent[value]=find(parent[value]);return parent[value]};private fun union(a:Int,b:Int){parent[find(a)]=find(b)};fun gcdSort(nums:IntArray):Boolean{val maximum=nums.maxOrNull()!!;parent=IntArray(maximum+1){it};for(value in nums){var remaining=value;var factor=2;while(factor*factor<=remaining){if(remaining%factor==0){union(value,factor);while(remaining%factor==0)remaining/=factor};factor++};if(remaining>1)union(value,remaining)};val sorted=nums.sortedArray();return nums.indices.all{find(nums[it])==find(sorted[it])}} }
